CREATE SCHEMA IF NOT EXISTS aiops;
CREATE TABLE IF NOT EXISTS aiops.runs(run_id text primary key,incident_id text not null,correlation_id text not null,mode text not null check(mode in('LIVE','DEMO','REPLAY','STORY')),state text not null,version bigint not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS aiops.run_events(event_id text primary key,run_id text not null references aiops.runs(run_id),sequence bigint not null,event_type text not null,payload jsonb not null,created_at timestamptz not null default now(),unique(run_id,sequence));
CREATE TABLE IF NOT EXISTS aiops.evidence(evidence_id text primary key,run_id text not null references aiops.runs(run_id),source_type text not null,source_locator text not null,observed_at timestamptz,known_at timestamptz not null default now(),provenance jsonb not null,confidence numeric(5,4),content jsonb not null);
CREATE TABLE IF NOT EXISTS aiops.decisions(decision_id text primary key,run_id text not null references aiops.runs(run_id),decision text not null,confidence numeric(5,4),reason jsonb not null,created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS aiops.remediations(remediation_id text primary key,run_id text not null references aiops.runs(run_id),decision_id text not null references aiops.decisions(decision_id),state text not null,created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS aiops.outbox(event_id text primary key references aiops.run_events(event_id),topic text not null,payload jsonb not null,status text not null default 'PENDING',attempts integer not null default 0,created_at timestamptz not null default now(),delivered_at timestamptz);
CREATE TABLE IF NOT EXISTS aiops.integration_receipts(receipt_id text primary key,event_id text not null references aiops.run_events(event_id),target text not null,idempotency_key text not null unique,status text not null,response jsonb,created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS aiops.schema_migrations(name text primary key,applied_at timestamptz not null default now());
